INSERT INTO `adventure_rank` VALUES (1,'L1','Wanderer','Every great journey begins with a single step.','Wanderer','/img/ranks/Wanderer.png',NULL,NULL,NULL,NULL,1,1),(2,'L2','Pathfinder','The first routes emerge from the wilderness.','Pathfinder','/img/ranks/Pathfinder.png',NULL,NULL,NULL,NULL,2,1),(3,'L3','Explorer','Curiosity reveals paths others overlook.','Explorer','/img/ranks/Explorer.png',NULL,NULL,NULL,NULL,3,1),(4,'L4','Trailblazer','New trails are forged through determination.','Trailblazer','/img/ranks/Trailblazer.png',NULL,NULL,NULL,NULL,4,1),(5,'L5','Voyager','The horizon expands with every discovery.','Voyager','/img/ranks/Voyager.png',NULL,NULL,NULL,NULL,5,1),(6,'L6','Expeditioner','No challenge is too distant or difficult.','Expeditioner','/img/ranks/Expeditioner.png',NULL,NULL,NULL,NULL,6,1),(7,'L7','Adventurer','The unknown becomes opportunity.','Adventurer','/img/ranks/Adventurer.png',NULL,NULL,NULL,NULL,7,1),(8,'L8','Pioneer','A leader among those who seek new routes.','Pioneer','/img/ranks/Pioneer.png',NULL,NULL,NULL,NULL,8,1),(9,'L9','Legend','Your name is etched among the greatest explorers.','Legend','/img/ranks/Legend.png',NULL,NULL,NULL,NULL,9,1);
